(7695941, 1262064, 102315, '<td valign="top">Perfect composition. Simply amazing. Top image</td>', 'Perfect composition. Simply amazing. Top image', '2021-06-11 21:37:22.000000', NULL, 1),
(7695984, 1262041, 30861, '<td valign="top">Gorgeous image, Lev, but exhibiting one of the landscape photographer''s great conundrums: although the horizon is actually leveled, it appears NOT to because of the wedge of wave-wash on the sand, and to some degree because of the pier overbalancing the right side... It''s a tough nut to crack...</td>', 'Gorgeous image, Lev, but exhibiting one of the landscape photographer''s great conundrums: although the horizon is actually leveled, it appears NOT to because of the wedge of wave-wash on the sand, and to some degree because of the pier overbalancing the right side... It''s a tough nut to crack...', '2021-06-13 23:22:44.000000', NULL, 1),
(7695985, 1262071, 30861, '<td valign="top">Best in show. By far. A stunning take on the challenge. Mariuca?</td>', 'Best in show. By far. A stunning take on the challenge. Mariuca?', '2021-06-13 23:25:33.000000', NULL, 1),
